session_start();require 'config/database.php';if(!isset($_SESSION['user'])){header('Location: login.php');exit;}$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT c.*,st.roll_no,st.semester_or_year,u.name,p.level,p.name program_name,p.specialization FROM student_certificates c JOIN students st ON st.id=c.student_id JOIN users u ON u.id=st.user_id JOIN programs p ON p.id=st.program_id WHERE c.id=?');$q->execute([$id]);$c=$q->fetch();if(!$c)exit('Certificate not found.');if($_SESSION['user']['role']==='student'){$q=$pdo->prepare('SELECT id FROM students WHERE user_id=?');$q->execute([$_SESSION['user']['id']]);if((int)$q->fetchColumn()!==(int)$c['student_id'])exit('Access denied.');}$labels=['bonafide'=>'Bonafide Certificate','character'=>'Character Certificate','enrollment'=>'Enrollment Certificate'];$title=$labels[$c['certificate_type']];$pageTitle=$title;require 'includes/header.php';?><div class="container py-5"><div class="certificate"><div class="text-center"><h1>IMCB F-10/4</h1><p>Islamabad Model College for Boys</p><hr><h2><?=htmlspecialchars($title)?></h2></div><div class="cert-body"><p>This is to certify that <strong><?=htmlspecialchars($c['name'])?></strong>, Roll No. <strong><?=htmlspecialchars($c['roll_no'])?></strong>, is a student of <strong><?=htmlspecialchars($c['program_name'])?></strong> (<?=htmlspecialchars($c['semester_or_year'])?>) at IMCB F-10/4.</p><?php if($c['purpose']):?><p>Purpose: <?=htmlspecialchars($c['purpose'])?></p><?php endif;?><p>This certificate is issued on <?=htmlspecialchars($c['issue_date'])?>.</p></div><div class="cert-meta"><span>Certificate No: <?=htmlspecialchars($c['certificate_no'])?></span><span>Issue Date: <?=htmlspecialchars($c['issue_date'])?></span></div><div class="signature"><span>____________________<br>Authorized Officer</span><span>____________________<br>Principal / Head</span></div></div><div class="text-center mt-3"><button class="btn btn-primary" onclick="window.print()">Print / Save PDF</button></div></div><style>.certificate{max-width:900px;margin:auto;border:12px double #173f68;padding:55px;background:#fff;min-height:720px}.cert-body{font-size:1.15rem;line-height:2;margin-top:50px}.cert-meta,.signature{display:flex;justify-content:space-between;margin-top:70px}.signature{text-align:center}@media print{.portal-nav,.btn,footer{display:none!important}.certificate{border:8px double #173f68;box-shadow:none}}</style><?php require 'includes/footer.php';?>
